from pathlib import Path
p=Path('/mnt/data/v38/main.py')
s=p.read_text()
s=s.replace('APP_VERSION = "V3.7.1-ARABIC-5TOP-STRATEGIES"','APP_VERSION = "V3.8-ARABIC-STRATEGY-HUNTER"')
# insert futures constants after BINANCE_API
s=s.replace('BINANCE_API = "https://data-api.binance.vision"','BINANCE_API = "https://data-api.binance.vision"\nFUTURES_API = "https://fapi.binance.com"')
# insert helper before get_exchange_info
marker='def get_exchange_info():\n'
insert='''def request_futures(path, params=None, timeout=TIMEOUT):\n    try:\n        r=requests.get(FUTURES_API+path,params=params or {},timeout=timeout)\n        r.raise_for_status(); return r.json()\n    except Exception:\n        return None\n\ndef obv_from_klines(raw):\n    k=completed(parse(raw))\n    if len(k)<3:return 0.0\n    obv=0.0\n    vals=[]\n    for i in range(1,len(k)):\n        if k[i]["c"]>k[i-1]["c"]: obv+=k[i]["v"]\n        elif k[i]["c"]<k[i-1]["c"]: obv-=k[i]["v"]\n        vals.append(obv)\n    if len(vals)<10:return 50.0\n    base=mean([abs(x) for x in vals[-20:]]) or 1.0\n    slope=(vals[-1]-vals[-6])/base*100.0 if len(vals)>=6 else 0\n    return round(clamp(50+slope*2.0),1)\n\ndef atr_pct(raw,n=14):\n    k=completed(parse(raw))\n    if len(k)<n+2:return 0.0\n    tr=[]\n    for i in range(1,len(k)):\n        tr.append(max(k[i]["h"]-k[i]["l"],abs(k[i]["h"]-k[i-1]["c"]),abs(k[i]["l"]-k[i-1]["c"])))\n    return round((mean(tr[-n:])/k[-1]["c"]*100),3) if k[-1]["c"] else 0.0\n\ndef sr_levels(raw, lookback=80):\n    k=completed(parse(raw))[-lookback:]\n    if len(k)<10:return {"support":None,"resistance":None,"support_distance":None,"resistance_distance":None}\n    price=k[-1]["c"]; lows=sorted([x["l"] for x in k if x["l"]<price], reverse=True); highs=sorted([x["h"] for x in k if x["h"]>price])\n    support=lows[0] if lows else min(x["l"] for x in k)\n    resistance=highs[0] if highs else max(x["h"] for x in k)\n    return {"support":round(support,12),"resistance":round(resistance,12),"support_distance":round((price-support)/price*100,3) if price else None,"resistance_distance":round((resistance-price)/price*100,3) if price else None}\n\ndef funding(symbol):\n    d=request_futures('/fapi/v1/premiumIndex',{'symbol':symbol})\n    try:\n        return float(d.get('lastFundingRate',0))*100 if d else None\n    except Exception:return None\n\ndef tf_metrics(symbol, interval, limit=100):\n    raw=get_klines(symbol,interval,limit); k=completed(parse(raw))\n    if len(k)<30:return {"interval":interval,"rsi":50.0,"obv":50.0,"volume_ratio":1.0,"atr_pct":0.0,"momentum":0.0,**sr_levels(raw)}\n    c=[x['c'] for x in k]; v=[x['v'] for x in k]\n    return {"interval":interval,"rsi":round(rsi(c),1),"obv":obv_from_klines(raw),"volume_ratio":round(v[-1]/(mean(v[-21:-1]) or v[-1]),2),"atr_pct":atr_pct(raw),"momentum":round(pct(c[-1],c[-6]),3),**sr_levels(raw)}\n\ndef strategy_scan():\n    d=get_data(); base=d.get('results',[])\n    # Only deepen a compact candidate pool; the final output is 5 per strategy.\n    pool=base[:60]\n    modes={\n      'scalp':('5m','15m'),'day':('15m','1h'),'swing':('1h','4h'),'invest':('4h','1d')\n    }\n    out={}; started=time.time()\n    for mode,(fast_tf,slow_tf) in modes.items():\n        rows=[]\n        def calc(c):\n            a=tf_metrics(c['symbol'],fast_tf,100); b=tf_metrics(c['symbol'],slow_tf,100)\n            acc=float(c.get('accumulation',50)); cvd=float(c.get('cvd',50)); liq=float(c.get('liquidity',50)); early=float(c.get('early_moon_ratio',50));\n            vol=min(100,a['volume_ratio']*50); rsi_score=clamp(100-abs(a['rsi']-55)*2.0)\n            if mode=='scalp':\n                score=clamp(a['rsi']*.08+clamp(a['volume_ratio']*50)*.16+a['obv']*.14+cvd*.22+liq*.15+early*.10+clamp(100-(a['resistance_distance'] or 10)*12)*.10+acc*.05)\n                reason='تدفق 5m + CVD + حجم + سيولة + قرب المقاومة'\n            elif mode=='day':\n                score=clamp(a['rsi']*.08+vol*.10+a['obv']*.12+cvd*.16+acc*.20+early*.14+b['rsi']*.08+clamp(100-(a['resistance_distance'] or 10)*10)*.12)\n                reason='تجميع 15m + اتجاه 1h + تدفق + استعداد للاختراق'\n            elif mode=='swing':\n                score=clamp(b['rsi']*.12+b['obv']*.14+acc*.22+early*.16+cvd*.10+liq*.10+clamp(100-(b['resistance_distance'] or 12)*7)*.10+clamp(100-abs(b['momentum']-4)*8)*.06)\n                reason='اتجاه 4h + تجميع + OBV + موقع سعري'\n            else:\n                # Investment is deliberately slower and more conservative: trend, OBV, liquidity, and distance from overextension.\n                trend_score=clamp(50+(b['rsi']-50)*1.2+(15 if b['obv']>=55 else 0)+(15 if c.get('tf_4h',50)>=55 else 0))\n                not_extended=clamp(100-max(0,float(c.get('change24h',0))-8)*4-max(0,float(c.get('momentum',50))-65)*1.2)\n                score=clamp(trend_score*.28+b['obv']*.18+acc*.18+liq*.12+early*.10+not_extended*.14)\n                reason='اتجاه 4h/1d + OBV + تجميع + سيولة + عقوبة التمدد'\n            # Reject obvious chase conditions in every mode, with stronger penalty for longer horizons.\n            penalty=0\n            if (a['rsi']>75 or a['momentum']>8): penalty=8 if mode in ('scalp','day') else 14\n            score=clamp(score-penalty)\n            return {**c,'strategy_score':round(score,1),'strategy':mode,'fast_tf':a,'slow_tf':b,'strategy_reason':reason,'chase_penalty':penalty}\n        with ThreadPoolExecutor(max_workers=12) as ex:\n            fs=[ex.submit(calc,c) for c in pool]\n            for f in as_completed(fs):\n                try: rows.append(f.result())\n                except Exception: pass\n        rows.sort(key=lambda x:x.get('strategy_score',0),reverse=True); out[mode]=rows[:5]\n    return {'status':'ok','version':APP_VERSION,'strategies':out,'candidate_pool':len(pool),'seconds':round(time.time()-started,2),'updated_at':int(time.time()*1000)}\n\ndef detailed_symbol(symbol):\n    symbol=symbol.upper().strip(); d=get_data(); current=next((x for x in d.get('results',[]) if x.get('symbol')==symbol),None)\n    if not current: raise RuntimeError('العملة غير موجودة في قائمة الرادار الحالية')\n    m15=tf_metrics(symbol,'15m',120); h1=tf_metrics(symbol,'1h',120); h4=tf_metrics(symbol,'4h',120); day=tf_metrics(symbol,'1d',120)\n    fnd=funding(symbol);\n    risk=clamp(100-(m15['atr_pct']*8)-max(0,float(current.get('change24h',0))-8)*3-(0 if (current.get('liquidity',50)>=60) else 12))\n    if fnd is not None and fnd>0.03:risk-=8\n    return {'status':'ok','version':APP_VERSION,'symbol':symbol,'price':current.get('price'),'change24h':current.get('change24h'),'quoteVolume24h':current.get('quoteVolume24h'),'funding_pct':round(fnd,5) if fnd is not None else None,'funding_label':'تمويل سالب' if fnd is not None and fnd<0 else ('تمويل موجب' if fnd is not None else 'غير متاح'),'risk':round(clamp(risk),1),'accumulation':current.get('accumulation'),'early_moon_ratio':current.get('early_moon_ratio'),'stage':current.get('stage_ar'),'cvd':current.get('cvd'),'flow':current.get('volume_pressure'),'whale':current.get('whale_hunter'),'liquidity':current.get('liquidity'),'volume_profile':current.get('volume_profile'),'support':m15.get('support'),'resistance':m15.get('resistance'),'support_distance':m15.get('support_distance'),'resistance_distance':m15.get('resistance_distance'),'rsi':m15.get('rsi'),'obv':m15.get('obv'),'volume_ratio':m15.get('volume_ratio'),'atr_pct':m15.get('atr_pct'),'timeframes':{'15m':m15,'1h':h1,'4h':h4,'1d':day},'why':current.get('why',[])}\n\n'''
s=s.replace(marker,insert+marker)
# Add endpoints before root
needle='@app.get("/")\n'
endpoints='''@app.get("/api/strategies")\ndef strategies():\n    try:return strategy_scan()\n    except Exception as e:return {"status":"error","version":APP_VERSION,"error":str(e)}\n\n@app.get("/api/details/{symbol}")\ndef details(symbol:str):\n    try:return detailed_symbol(symbol)\n    except Exception as e:return {"status":"error","version":APP_VERSION,"error":str(e)}\n\n'''
s=s.replace(needle,endpoints+needle)
p.write_text(s)
